using System;

public class C
{
    public static void Main()
    {
        X x = new X();
        Y y = new Y();
        Console.WriteLine((1, ((int, int))x) == (y, (1, 1)));
     }
}

class X
{
    public static implicit operator (short, short)(X x)
    {
        Console.WriteLine("X-> (short, short)");
        return (1, 1);
    }
}

class Y
{
    public static implicit operator int(Y x)
    {
        Console.WriteLine("Y -> int");
        return 1;
    }
}
